<?php
if (session_status()===PHP_SESSION_NONE) { session_name('gameserverpanel_web'); session_start(); }
require_once __DIR__.'/bootstrap.php'; require_once __DIR__.'/includes/admin_auth.php'; require_once __DIR__.'/includes/action_security.php';
require_once __DIR__.'/classes/BillingRepository.php'; require_once __DIR__.'/classes/RefundCalculator.php'; require_once __DIR__.'/classes/GatewayFactory.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$db=mysqli_connect($db_host,$db_user,$db_pass,$db_name,isset($db_port)?(int)$db_port:null); mysqli_set_charset($db,'utf8mb4'); $p=$table_prefix??'gsp_';
$csrf=billing_action_csrf_token('billing_admin_cancellation_csrf'); $msg='';
if ($_SERVER['REQUEST_METHOD']==='POST' && billing_action_validate_csrf($_POST['csrf']??'','billing_admin_cancellation_csrf')) {
    $id=(int)($_POST['request_id']??0); $decision=$_POST['decision']??''; $admin=(int)($_SESSION['website_user_id']??$_SESSION['user_id']??0);
    $q=$db->prepare("SELECT r.*, h.server_expiration_date, h.next_invoice_date, o.payment_txid, o.paypal_data, o.price, o.invoice_duration, i.invoice_id, i.total_due, i.period_start, i.period_end, i.currency, i.payment_txid AS invoice_txid FROM {$p}billing_cancellation_requests r JOIN {$p}server_homes h ON h.home_id=r.home_id LEFT JOIN {$p}billing_orders o ON o.order_id=r.order_id LEFT JOIN {$p}billing_invoices i ON i.home_id=r.home_id AND i.payment_status='paid' WHERE r.request_id=? ORDER BY i.invoice_id DESC LIMIT 1");
    if ($q) { $q->bind_param('i',$id); $q->execute(); $r=$q->get_result()->fetch_assoc(); $q->close(); } else $r=null;
    if ($r && ($r['status']??'')==='pending' && in_array($decision,['approve','reject'],true)) {
        if ($decision==='reject') { $s=$db->prepare("UPDATE {$p}billing_cancellation_requests SET status='rejected',decided_at=NOW(),decided_by=?,note=? WHERE request_id=?"); $note=(string)($_POST['note']??''); $s->bind_param('isi',$admin,$note,$id); $s->execute(); $s->close(); $msg='Request rejected.'; }
        elseif ($r['mode']==='end_of_term') { $s=$db->prepare("UPDATE {$p}server_homes SET cancel_at_expiry=1 WHERE home_id=?"); $s->bind_param('i',$r['home_id']); $s->execute(); $s->close(); $s=$db->prepare("UPDATE {$p}billing_cancellation_requests SET status='completed',decided_at=NOW(),decided_by=? WHERE request_id=?"); $s->bind_param('ii',$admin,$id); $s->execute(); $s->close(); $msg='End-of-term cancellation approved.'; }
        else { $amount=(float)($r['refund_amount']??$r['total_due']??$r['price']??0); $currency=$r['currency']??'USD'; $s=$db->prepare("UPDATE {$p}billing_cancellation_requests SET status='approved',decided_at=NOW(),decided_by=?,refund_amount=?,refund_status='pending' WHERE request_id=?"); $s->bind_param('idi',$admin,$amount,$id); $s->execute(); $s->close();
            $gateway=GatewayFactory::make('paypal'); $refund=$gateway->refund(['capture_id'=>$r['invoice_txid']??$r['payment_txid']??'','amount'=>$amount,'currency'=>$currency,'idempotency_key'=>'cancel-'.$id]);
            $status=!empty($refund['success'])?($refund['status']??'refunded'):'failed'; $final=$status==='failed'?'failed':'completed'; $s=$db->prepare("UPDATE {$p}billing_cancellation_requests SET status=?,refund_status=?,refund_txid=? WHERE request_id=?"); $tx=(string)($refund['transaction_id']??''); $s->bind_param('sssi',$final,$status,$tx,$id); $s->execute(); $s->close(); if ($final==='completed') { $s=$db->prepare("UPDATE {$p}server_homes SET billing_status='cancelled',billing_enabled=0 WHERE home_id=?"); $s->bind_param('i',$r['home_id']); $s->execute(); $s->close(); } $msg=$final==='completed'?'Cancellation approved and refund processed.':'Refund failed; service was not deleted.'; }
    }
}
$rows=[]; $res=$db->query("SELECT r.*,u.users_email,h.home_name,o.price,i.period_start,i.period_end,i.currency FROM {$p}billing_cancellation_requests r LEFT JOIN {$p}users u ON u.user_id=r.user_id LEFT JOIN {$p}server_homes h ON h.home_id=r.home_id LEFT JOIN {$p}billing_orders o ON o.order_id=r.order_id LEFT JOIN {$p}billing_invoices i ON i.home_id=r.home_id AND i.payment_status='paid' WHERE r.status='pending' GROUP BY r.request_id ORDER BY r.requested_at");
if($res) { $rows=$res->fetch_all(MYSQLI_ASSOC); foreach($rows as &$row) { $row['computed_refund']=RefundCalculator::calculate((float)($row['price']??0), (string)($row['period_start']??''), (string)($row['period_end']??''), time(), 30); } unset($row); }
mysqli_close($db);
?><?php if (!billing_is_panel_context()): ?><!doctype html><html><head><meta charset="utf-8"><title>Billing cancellations</title></head><body><?php endif; ?><h1>Pending cancellations</h1><p><?=h($msg)?></p><table><tr><th>Customer</th><th>Service</th><th>Mode</th><th>Refund</th><th>Requested</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r['users_email'])?></td><td><?=h($r['home_name'])?></td><td><?=h($r['mode'])?></td><td><?=number_format((float)$r['computed_refund'],2)?> <?=h($r['currency']??'USD')?></td><td><?=h($r['requested_at'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="request_id" value="<?=(int)$r['request_id']?>"><button name="decision" value="approve">Approve</button><button name="decision" value="reject">Reject</button><input name="note" placeholder="rejection note"></form></td></tr><?php endforeach; ?></table><?php if (!billing_is_panel_context()): ?></body></html><?php endif; ?>
